quests[44442] = { id = 44442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: New Blood 5" }
quests[44443] = { id = 44443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen der Ahnen", description = "Ihr habt Euch viele Male als <einzigartiger Druide/einzigartige Druidin> bewiesen, aber um den Kampf gegen die Brennende Legion zu bestehen, müsst Ihr jede Gelegenheit nutzen, um einen Vorteil über Eure Feinde zu erlangen.\n\nIhr solltet überlegen, noch eine letzte Waffe der Ahnen zu besorgen. Ihre Kräfte werden Euch dabei helfen, allen Angriffsversuchen der Legion standzuhalten.\n\nLasst mich wissen, wie Ihr vorgehen wollt.", sourceObjective = "Wählt ein viertes Artefakt, nach dem Ihr suchen wollt.", completion = "Eine gute Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[44444] = { id = 44444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Chosen" }
