quests[44447] = { id = 44447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resto Chosen" }
quests[44448] = { id = 44448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Haus von Licht und Schatten", description = "Die Tränen von Elune sind für Euch bereit, {name}. Ich bin mir aber nicht sicher, wie es weitergeht. Bringt das Relikt zurück zu Eurer Ordenshalle und versucht, es auf das Herz des Lichts anzuwenden.\n\nVielleicht müssen sie sich berühren? Ich kann da wirklich auch nur raten.\n\nHoffen wir, dass es funktioniert!", sourceObjective = "Bringt die Tränen von Elune zum Herz des Lichts in Eurer Ordenshalle.", progress = "Gibt es Neuigkeiten?", completion = "Tot? Die Titanen sind tot?\n\n<Khadgar grübelt kurz über diese Neuigkeiten nach.>\n\nDas erklärt vieles, aber dennoch erfüllt es mich mit großer Traurigkeit. Wir waren so lange auf uns allein gestellt. Unsere Götter wurden getötet, bevor wir geboren wurden.\n\nWas die Armee des Lichts und Illidan betrifft, weiß ich auch keinen Rat. Ich habe mich noch nie so machtlos gefühlt.\n\nIllidan ist tot und die Goldene Armee kämpft in unserem Namen einen endlosen Krieg im gesamten Kosmos.\n\nIch muss einen Moment nachdenken, {name}. Das sind fast zu viele schlechte Nachrichten für einen alten Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[44449] = { id = 44449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablöschen für Fortgeschrittene", description = "Jetzt da wir einen Frostmagier zur Verfügung haben, sollte es doch ein Kinderspiel sein, diese Methode auszutesten.\n\nHier sind die Pläne für die gewünschten Gegenstände. Macht Euch an die Arbeit und bringt mir gleich die Armschützer, wenn Ihr fertig seid.", sourceObjective = "Stellt ein Paar Hartleysteinarmschützer für Alard her.", progress = "Wie läuft's denn mit dieser Technik?", completion = "Schaut Euch mal an, wie das glänzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[44455] = { id = 44455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downfall Tracking" }
quests[44457] = { id = 44457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruderliebe", description = "Maiev muss irgendwo in diesem Kerker sein. Auf dem Weg hierher fand ich ihre abgestreifte Rüstung.\n\nIch hörte, Ihr kennt sie bereits, und ich hoffe, dass dies kein Problem darstellen wird.\n\nWir sollten uns aufteilen, um die Zellen schneller abzusuchen. Wir müssen sie finden.", sourceObjective = "Sucht Maiev Schattensang im Kerker der Rabenwehr.\n\nBereitgestellter Gegenstand:", completion = "<Maievs Gesicht ist blutunterlaufen, ihre Lippen sind aufgeplatzt und ihr Körper ist mit Narben übersät. Sie sieht mager und erschöpft aus, aber ihre Bewegungen sind immer noch kraftvoll.>\n\nWochenlang haben sie versucht, mich zu brechen, diese Amateure!\n\nIch habe geschwiegen, die Minuten gezählt, ihre Schritte geschätzt und den Stimmen außerhalb meiner Zelle gelauscht.\n\nIch habe auf meine Chance gewartet, um meinen Peinigern zu entkommen und mich zu rächen.\n\nUnd jetzt bringt Ihr mir meine Rüstung UND mein Schwert. Jetzt ist es an Euch, mich zu befreien, {class}. Lasst uns die Legion zusammen vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[44458] = { id = 44458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 1" }
