quests[44462] = { id = 44462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Blood of Our Enemy 5" }
quests[44463] = { id = 44463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen unter ihnen", description = "Unser Verdacht hat sich bewahrheitet, {name}! Die Dämonen dachten, sie könnten uns überrumpeln.\n\nSchnell! Zu den Waffen! Warnt den König!", sourceObjective = "Beschützt den König.", completion = "Ich muss gestehen, dass Ihr uns womöglich vor einer schrecklichen Tragödie bewahrt habt. Ich möchte Euch meinen Dank aussprechen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44464] = { id = 44464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederauferstehung", description = "Das Herz des Lichts wird als Behältnis für Illidan Sturmgrimms Wiedergeburt dienen. Dies ist mein letzter Dienst für das Licht.\n\nAber Illidan ist tot und seine Seele im Nether verschollen. Bevor wir es wagen können, seine Seele zurückkehren zu lassen, müssen wir das Behältnis auf seine Rückkehr vorbereiten.\n\nDie Echos von Illidans Vergangenheit lassen sich in zwei Welten finden. Ihr müsst Euch auf die Suche nach den Echos begeben.\n\nFangt dort an, wo alles Leben beginnt, {name}: bei der Geburt. Findet Illidans Geburtsort in Val'sharah. Lasst die Erinnerung aufleben.", sourceObjective = "Reist nach Val'sharah und werdet Zeuge der ersten Momente in Illidan Sturmgrimms Leben.", progress = "Wenn unsere Arbeit getan ist, werde ich in die Großen Dunklen Weiten einziehen.", completion = "Ein vielversprechender Start in ein tragisches Leben. Vielleicht einer der wenigen freudvollen Momente in Illidans Leben. Aber obwohl die darauf folgenden Jahre eine Herausforderung für das Kind der Prophezeiung darstellten, ließ es sich nie unterkriegen. Daran solltet Ihr immer denken, unabhängig von dem, was Ihr auf unserer Reise sehen werdet.\n\nEs gibt noch viel zu tun, aber ich bin noch nicht bereit. Ich werde Euch rufen, wenn es soweit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[44465] = { id = 44465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutieren der Erdenrufer", description = "Felinda Frye hat sich uns kürzlich am Herz von Azeroth angeschlossen. Sie leitet die Rekrutierung und die Ausbildung Eurer Erdenrufer.\n\nIch würde Euch empfehlen, so schnell wie möglich mit ihr zu sprechen, <Scharfseher/Scharfseherin> {name}. Die Erdenrufer sind mächtige Schamanen, die unsere Streitmacht enorm verstärken können.", sourceObjective = "Sprecht mit Felinda Frye.", completion = "Seid gegrüßt, Scharfseher {name}. Ich habe schon auf Euch gewartet.\n\nDie Erdenrufer sind bereit, Eure Befehle auszuführen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44466] = { id = 44466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unklarer Weg", description = "Viele seiner prägendsten Jahre hat Illidan zusammen mit seinem Zwillingsbruder Malfurion in Val'sharah verbracht.\n\nAls junge Nachtelfen buhlten beide Zwillingsbrüder um die Gunst der jungen Priesterin Tyrande und stellten sich deshalb den Prüfungen des Halbgottes Cenarius.\n\nWir müssen jetzt zum Hain der Träume reisen, denn dort entscheidet sich Illidans wahrer Weg.", sourceObjective = "Werdet Zeuge von Illidans Unbeugsamkeit im Hain der Träume in Val'sharah.", progress = "Ihr dürft die Hoffnung nicht verlieren.", completion = "Fehlschlag. Zurückweisung. Von diesem Tag an waren dies Illidans Begleiter. Aber unverdrossen begab er sich weiter auf der Suche nach seinem Schicksal. Und es tat sich ein weiterer Weg auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[44467] = { id = 44467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: When There's a Will, There's a Way 1" }
quests[44468] = { id = 44468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: When There's a Will, There's a Way 2" }
