quests[44470] = { id = 44470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: When There's a Will, There's a Way 4" }
quests[44471] = { id = 44471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweites Gesicht", description = "Der junge König Anduin hat zwar ein gutes Herz, aber ihm mangelt die Entschlossenheit seines Vaters. Die Allianz braucht einen Anführer, der das Heft des Handelns in die Hand nimmt. Die Legion schlägt sofort zu, wenn sie Schwäche wahrnimmt.\n\nUnd gerade jetzt spüre ich, dass etwas nicht stimmt, {name}. Ich fürchte, dass der Schein trügt.\n\nSchnell! Verwendet Eure Geistersicht. Wir müssen überprüfen, ob Feinde unter uns weilen.", sourceObjective = "Verwendet Eure Fähigkeit 'Geistersicht'.", progress = "Die Zeit läuft uns davon.", completion = "Es war ja klar, dass die Legion versuchen würde, das Begräbnis zu infiltrieren. Alle Anführer der Allianz gleichzeitig an einem Ort... Da kann ja wirklich kein Dämon widerstehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44472] = { id = 44472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: When There's a Will, There's a Way 5" }
quests[44473] = { id = 44473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Waffe der Allianz", description = "Zunächst war ich unsicher, ob wir die Illidari in die Stadt lassen sollten. Aber Ihr könntet tatsächlich unser aller Leben gerettet haben.\n\nIch erlaube Euch, ein Lager im Magierviertel einzurichten. Die Allianz wird Eure Hilfe brauchen, wenn sie gegen die Legion in den Kampf zieht.\n\nAber seid gewarnt: Wenn Ihr den Teufelsenergien, mit denen Ihr herumspielt, verfallt und zu einem Dämon werdet, werden wir Euch auch wie andere Dämonen behandeln.", sourceObjective = "Trefft Euch mit den Illidari im Magierviertel von Sturmwind.", completion = "Dem jungen König geht es hoffentlich gut.\n\nWir haben noch immer zu tun, {class}. Noch eine ganze Menge.", sourceObjectiveStatus = "unverified-source-field" }
quests[44474] = { id = 44474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Following In His Footsteps 1" }
