quests[44479] = { id = 44479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenkrones Vermächtnis", description = "Jahre später, als bereits der Krieg der Ahnen tobte und die Brennende Legion diese Welt bedrängte, machte Illidan die Bekanntschaft von Kur'talos Rabenkrone, einem großen militärischen Anführer. Und auch er erkannte das Potenzial von Illidan und machte ihn schließlich zum Hauptmann der Mondwache, einer mächtigen Gruppe von Nachtelfenzauberern.\n\nWir müssen Zeugen dieser Erinnerung in der Rabenwehr an der Westküste von Val'sharah werden.", sourceObjective = "Werdet Zeuge von Rabenkrones Vermächtnis in der Rabenwehr in Val'sharah.", completion = "Es ist ein schmaler Grat zwischen Gut und Böse, und wohlmeinende Absichten sind dabei ohne Bedeutung.\n\nIllidan verzweifelte daran, dass seine Umwelt so blind für die Bedrohung durch die Brennende Legion war. Das Schicksal ist mitunter ein Meister der Ironie.", sourceObjectiveStatus = "unverified-source-field" }
quests[44480] = { id = 44480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In meines Vaters Haus", description = "Die meisten Sterblichen können die Wahrheit über die Legion nicht verstehen. Und jene, die es doch tun, verschließen sich oftmals ihrer Bedeutung. Das Wissen darum kann eine zu große Bürde für das Wesen eines Sterblichen sein, denn ein solches Opfer zu bringen, verändert auf ewig die Seele.\n\nUnter den größten Eurer Helden haben nur wenige dieses Opfer verstanden. Lasst es uns durch Illidans Augen mitansehen.\n\nWir müssen uns nach Azshara auf dem Kontinent Kalimdor begeben.", sourceObjective = "Werdet Zeuge von Illidans Opfer in Azshara auf dem Kontinent Kalimdor.", progress = "Das Behältnis ist fast bereit, die Seele aufzunehmen.", completion = "Illidan suchte nach der Wahrheit, aber das, was er erblickte, blendete ihn. Er begann, sein Schicksal zu verstehen, aber er musste noch ein letztes Opfer bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44481] = { id = 44481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerfülltes Schicksal", description = "Er war zwar kaum noch als das goldäugige Kind der Prophezeiung wiedererkennbar und lebte als Ausgestoßener am Rande einer zerschmetterten Welt, aber sein Antrieb war ungebrochen. Er konzentrierte sich nur darauf, die Legion anzugreifen und ihren Vorstoß aufzuhalten.\n\nUnd dennoch, in einer fast ironischen Geste des Schicksals, war es am Ende nicht die Brennende Legion, die sein Ende bedeutete.\n\nWir müssen in die Scherbenwelt reisen, um Illidans letzte Erinnerung in Erfahrung zu bringen.", sourceObjective = "Werdet Zeuge des wahren Verrats im Schattenmondtal am Rande der Scherbenwelt.", completion = "Ich musste weinen, als ich Euer Bewusstsein in den Großen Dunklen Weiten berührte, Sterblicher. Denn ich sah seinen Untergang. Und ich sah Euch und wie Euer Schatten sich wie ein dunkles Leichentuch über seinen Leichnam legte. Ich spürte, wie der Hass in Eurem Herzen begann, Eure Seele zu verderben.\n\nEs war nicht das Herz des Lichts, das vorbereitet werden musste, sondern Ihr. Jetzt kennt Ihr die Wahrheit. Seid Ihr bereit zu tun, was getan werden muss, um unsere und alle anderen Welten zu retten?\n\nWenn die Zeit gekommen ist, werde ich Euch bitten, nach Illidans Seele zu suchen.\n\nSeine Wiedergeburt ist die Vorrausetzung Eurer Erlösung.", sourceObjectiveStatus = "unverified-source-field" }
quests[44482] = { id = 44482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rekrutieren der Ritter der Schwarzen Klinge", description = "Korgaz Totaxt hat unermüdlich daran gearbeitet, eine neue Generation Todesritter auszubilden.\n\nEr hat fantastische Arbeit geleistet, indem er die schwächsten unter ihnen aussortiert hat. Alle, die die Prüfungen der Ausbildung zum Todesritter überlebt haben, sind jetzt bereit, sich der Schwarzen Klinge anzuschließen.\n\nKorgaz wartet auf Euch auf der oberen Ebene. Ich würde Euch empfehlen, so schnell wie möglich mit ihm zu sprechen.\n\nDie neuen Todesritter werden eine große Verstärkung unserer Streitmacht im Kampf gegen die Brennende Legion darstellen.", sourceObjective = "Sprecht mit Korgaz Totaxt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44483] = { id = 44483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vendor Beckon Trigger - Druid" }
quests[44484] = { id = 44484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vendor Beckon Trigger - Druid" }
quests[44486] = { id = 44486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsversehrter Foliant", description = "Ein großer Teil der Elfenschriften in dem Folianten ist von Teufelsfeuer versengt worden.\n\nDer oberste Kurator in Dalaran ist bekannt für sein Können bei der Restauration solcher Werke. Vielleicht kann er den Folianten wieder lesbar machen.", sourceObjective = "Bringt den teufelsversehrten Folianten zu Robert Newhearth in Dalaran.", progress = "Oh, was gibt es jetzt wieder?", completion = "Ah, diese Brandstellen kann man mit den richtigen alchemistischen Tinkturen wieder lesbar machen.\n\nSehr interessant. Ein gehobener darnassischer Schreibstil mit... dämonischen Idiomen.\n\nIch glaube, ich weiß, wer das verfasst hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[44487] = { id = 44487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässter Foliant", description = "Trotz seiner magischen Eigenschaften wurde das Buch vom Wasser beschädigt.\n\nDer oberste Kurator in Dalaran ist bekannt für seine Fähigkeiten. Womöglich kann er es restaurieren.", sourceObjective = "Bringt den durchnässten Folianten zu Robert Newhearth in Dalaran.", progress = "Was haben wir denn hier?", completion = "Diese Handschrift würde ich überall wiedererkennen. Das ist das Tagebuch von Khadgar selbst!", sourceObjectiveStatus = "unverified-source-field" }
quests[44488] = { id = 44488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfluchter Foliant", description = "Ein großer Teil der Elfenschriften in dem Folianten ist von Teufelsfeuer versengt worden.\n\nDer oberste Kurator in Dalaran ist bekannt für sein Können bei der Restauration solcher Werke. Vielleicht kann er den Folianten wieder lesbar machen.", sourceObjective = "Bringt den teufelsversehrten Folianten zu Robert Newhearth in Dalaran.", progress = "Oh, was gibt es jetzt wieder?", completion = "Diese Texte werden von verderbter Magie geschützt.\n\nSie ist viel stärker als alles, was ich zuvor gesehen habe. Aber unsere Magier werden eine Lösung dafür finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[44489] = { id = 44489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyana Düstergram", description = "<Lyana Düstergram, Eure Illidarigefährtin, schwebt vor Euch in Stasis. Ihre Seele wird langsam in den Erntekristall hineingesogen.>\n\n<Ihr müsst den Seelenernter vernichten, wenn Ihr sie aus der Stasis befreien wollt.>", sourceObjective = "Vernichtet den Seelenernter.", completion = "{name}, selten haben ich mich so über Euren Anblick gefreut. Danke, dass Ihr mich befreit habt.\n\nIch weiß gar nicht, wie lange ich gefangen gehalten wurde... Aber ich spüre, dass sich eine große Anzahl Dämonen in der Nähe befindet.\n\nEs gibt hier noch viel zu tun. Wollt Ihr mich begleiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[44490] = { id = 44490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmschwinge die Verschlingerin", description = "Danke, dass Ihr mich aus der Gefangenschaft befreit habt, {name}.\n\nAllerdings ist Azoran kein gewöhnlicher Dämon, sondern ein mächtiger Eredar, der einen hohen Rang in der Brennenden Legion einnimmt.\n\nBevor wir uns aber um ihn kümmern können, müssen wir einen anderen Gegner ausschalten.\n\nGrimmschwinge die Verschlingerin ist die Stärkste unter den Teufelsfledermäusen. Platziert das Basiliskenfleisch auf dem Altar im Norden und tötet Grimmschwinge, wenn sie auftaucht.\n\nBringt mir dann ihren Kopf. Mein Rachedurst muss gestillt werden.", sourceObjective = "Tötet Grimmschwinge die Verschlingerin.", progress = "Was bringt Ihr für Neuigkeiten über Grimmschwinge die Verschlingerin?", completion = "Grimmschwinge war eine furchterregende Dämonin... Ich muss sagen, dass mich Eure Fähigkeiten immer wieder beeindrucken, {name}.\n\nEs gibt hier noch sehr viel mehr Dämonen zu töten. Es ist gut, Euch wieder an meiner Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44491] = { id = 44491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar Collapse Scenario - Run Once" }
quests[44492] = { id = 44492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienlehrling", description = "Diese weiteren Leylinienzuleitungen zu finden, war gute Arbeit.\n\nFür jemanden, der nicht von hier ist, seid Ihr erstaunlich kompetent.\n\nIch möchte Euch ein paar Geheimnisse über die Macht der Leylinien verraten. Das wird Euch dabei helfen, mehr uraltes Mana von den Wesen in der Gegend um Suramar einzusammeln. Das ist eine grausame Aufgabe, das weiß ich. Und genau darum überlasse ich sie Euch!", sourceObjective = "Sprecht mit Arkanistin Valtrois.", completion = "Hört gut zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[44493] = { id = 44493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienkenntnisse", description = "Unsere Leylinienzuleitung wird stärker.\n\nUnd je stärker unsere Zuleitung wird, desto mehr lerne ich über das uralte Mana selbst.\n\nAls <mein Schüler/meine Schülerin> profitiert Ihr natürlich auch von meinen Entdeckungen. Hört gut zu, dann erzähle ich Euch, wie Ihr viel effizienter Energie aus Euren Gegnern bezieht.", sourceObjective = "Sprecht mit Arkanistin Valtrois.", completion = "Versucht, es am besten gleich zu verstehen. Ich hasse es, mich wiederholen zu müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44495] = { id = 44495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinienmeister", description = "Ihr überrascht mich, <Fremder/Fremde>. Während unserer ersten Lektion über die uralten Leylinien hatte ich fast erwartet, dass Ihr Euch in Tagträumen über Abenteuer, Schätze oder anderen Nonsens verliert.\n\nAber Ihr scheint gut aufgepasst zu haben.\n\nUnsere Leylinienzuleitung ist extrem mächtig geworden, und durch das Beobachten dieses Prozesses konnte ich viel über arkane Zusammenhänge und die Natur des Manas lernen.\n\nIch habe noch eine abschließende Lektion für Euch, wie Ihr noch mehr uraltes Mana finden könnt.", sourceObjective = "Sprecht mit Arkanistin Valtrois.", completion = "Vielleicht gibt es doch noch Hoffnung für Fremde wie Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44496] = { id = 44496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerfülltes Schicksal", description = "Er war zwar kaum noch als das goldäugige Kind der Prophezeiung wiedererkennbar und lebte als Ausgestoßener am Rande einer zerschmetterten Welt, aber sein Antrieb war ungebrochen. Er konzentrierte sich nur darauf, die Legion anzugreifen und ihren Vorstoß aufzuhalten.\n\nUnd dennoch, in einer fast ironischen Geste des Schicksals, war es am Ende nicht die Brennende Legion, die sein Ende bedeutete.\n\nWir müssen in die Scherbenwelt reisen, um Illidans letzte Erinnerung in Erfahrung zu bringen.", sourceObjective = "Werdet Zeuge des wahren Verrats im Schattenmondtal am Rande der Scherbenwelt.", progress = "Wenn das Behältnis vorbereitet ist, werden wir seine Seele suchen.", completion = "Letzten Endes waren es die Bewohner von Azeroth und der Scherbenwelt, die Illidan aus Rache auslöschten. Ihr habt zwar nicht selbst die Hand gegen ihn erhoben, aber Ihr seid mitschuldig an seinem Untergang.\n\nIch habe Euch Illidans Leben gezeigt, damit Ihr versteht, warum er gekämpft und seine Entscheidungen getroffen hat, wie er es tat. Ihr selbst wart das Behältnis, das vorbereitet werden musste.\n\nWenn Hass und Zweifel aus Eurem Herzen verschwunden sind, sollt Ihr den Platz an der Seite des Lichts einnehmen. Ich werde Euch schon bald rufen, damit wir uns auf die Suche nach Illidans Seele begeben können.", sourceObjectiveStatus = "unverified-source-field" }
quests[44497] = { id = 44497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerfülltes Schicksal", description = "Er war zwar kaum noch als das goldäugige Kind der Prophezeiung wiedererkennbar und lebte als Ausgestoßener am Rande einer zerschmetterten Welt, aber sein Antrieb war ungebrochen. Er konzentrierte sich nur darauf, die Legion anzugreifen und ihren Vorstoß aufzuhalten.\n\nUnd dennoch, in einer fast ironischen Geste des Schicksals, war es am Ende nicht die Brennende Legion, die sein Ende bedeutete.\n\nWir müssen in die Scherbenwelt reisen, um Illidans letzte Erinnerung in Erfahrung zu bringen.", sourceObjective = "Werdet Zeuge des wahren Verrats im Schattenmondtal am Rande der Scherbenwelt.", completion = "Vergebt mir, edle Seele. Ich habe Euch auf die falsche Fährte geführt. Nicht das Herz des Lichts war das Behältnis, das vorbereitet werden musste, sondern Ihr selbst.\n\nIhr habt alles für Eure Welt geopfert und Eurem Meister bis zum Ende treu gedient. Diese Erinnerungen werden Eure Entschlossenheit noch bekräftigen. Besinnt Euch auf sie, wenn die dunkle Verführung Euch umgarnt, und lasst sie Euren Widerstand gegen die Mächte der Verderbnis stärken.\n\nWir werden Illidan retten und Ihr werdet erneut an der Seite Eures Meisters um das Schicksal aller Welten kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44498] = { id = 44498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterhufsäuberung", description = "Ich habe das Totem angefertigt, um den Brunnen der Winterhufe zu säubern. Jetzt müsst Ihr es zum Brunnen bringen und ein Säuberungsritual durchführen. Ihr findet den Brunnen im Südosten, aber nehmt Euch in Acht. Wer auch immer für diese Schandtat verantwortlich war, wird dort eventuell auf der Lauer liegen.\n\nEs kann sein, dass diese Aufgabe sehr schwierig ist, {name}. Seid vorsichtig, und lasst diejenigen, die unseren Brunnen entweiht haben, nicht entkommen.", sourceObjective = "Benutzt das Läuterungstotem der Winterhufe beim Brunnen der Winterhufe.", sourceObjectiveStatus = "unverified-source-field" }
quests[44499] = { id = 44499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowfang Tracking Quest" }
quests[44500] = { id = 44500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dichter und Denker", description = "Wir haben uns den in Karazhan gefundenen Folianten noch einmal angesehen. Obwohl wir Verweise auf die Säulen der Schöpfung entdeckt haben, fehlt eine Schlüsselinformation in dem Buch... wo die Artefakte zu finden sind.\n\nGlücklicherweise können wir auf einen Experten auf diesem Gebiet zurückgreifen.\n\nDer Verfasser, Alodi, war der erste Wächter von Tirisfal. Sein Geist ist für alle Zeiten an die Schmiede des Wächters gebunden, die zur sicheren Aufbewahrung von uns versteckt wurde. Ich glaube, es ist an der Zeit, ihn anzurufen.", sourceObjective = "Sagt Khadgar, er soll mit dem Ritual beginnen, um den Geist von Alodi, dem ersten Wächter, zu beschwören.", progress = "Alodis Wissen um die Säulen der Schöpfung ist für unseren Kampf gegen die Legion absolut entscheidend.", completion = "Wir kennen zwar nicht den genauen Ort, an dem sich die Säulen der Schöpfung befinden, aber immerhin wissen wir, wo wir anfangen können. Wir werden jeden Winkel der Verheerten Inseln erkunden, bis wir sie gefunden haben.\n\nDie Legion intensiviert ihre Angriffe. Wir müssen uns darauf vorbereiten, Dalaran zu den Verheerten Inseln zu verlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44501] = { id = 44501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
