quests[44543] = { id = 44543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Verheerte Küste", description = "Dieser Windreiter wird Euch zur Verheerten Küste bringen, {name}. Möge Euch Eure Waffe heute viele Trophäen einbringen.\n\nDer Kriegshäuptling ist schon an Land gegangen. Ich denke, Ihr müsst einfach nur der Spur Dämonenblut folgen.", sourceObjective = "Nehmt den Windreiter zur Verheerten Küste.", completion = "Gut, dass Ihr wieder auf den Beinen seid, {name}. Viele tapfere Soldaten, die zur Verheerten Küste gesegelt sind, hatten nicht so viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[44544] = { id = 44544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Irdenen Rings", description = "Endlich habe ich Euch gefunden!\n\nIch habe eine Nachricht von Berater Sevel.\n\nDer Irdene Ring braucht Eure Hilfe, <Scharfseher/Scharfseherin>. Bitte kehrt so schnell wie möglich zum Herz von Azeroth zurück. Berater Sevel wartet bereits auf Euch.", sourceObjective = "Sprecht mit Berater Sevel.", completion = "Es ist gut, dass Ihr hier seid, Scharfseher. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44545] = { id = 44545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Sturmangriff vorantreiben", description = "<Nachdem diese Säule der Schöpfung sicher unter Eurer Kontrolle ist, solltet Ihr Euren Schwung nutzen und Euch auf die Suche nach der nächsten machen.>\n\n<Ihr erinnert Euch, dass Euer Orden Informationen hat, die Euch behilflich sein könnten. Es wäre klug, sich diese vor Antritt der Reise noch einmal anzusehen.>", sourceObjective = "Wählt Euren nächsten Angriffspunkt auf den Verheerten Inseln auf der Schlachtkarte in Eurer Ordenshalle aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44546] = { id = 44546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südlich von Burg Schattenfang im Silberwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 12 Mitarbeiter der Chemiemanufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport südlich von Burg Schattenfang im Silberwald zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44547] = { id = 44547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inselhüpfen", description = "<Nach dem errungenen Sieg wisst Ihr, dass es immer noch Säulen der Schöpfung gibt, die geborgen werden müssen, wenn die Legion endgültig bezwungen werden soll.>\n\n<Euer Orden hat bisher unbekannte Regionen der Verheerten Inseln ausgemacht, in denen sich immer noch die restlichen Säulen befinden. Es würde Euren Bemühungen sicherlich helfen, wenn Ihr Euch die Informationen anseht.>", sourceObjective = "Wählt Euren nächsten Angriffspunkt auf den Verheerten Inseln auf der Schlachtkarte in Eurer Ordenshalle aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44548] = { id = 44548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste durchwühlen", description = "<Als Ihr Euch in der Kammer umseht, merkt Ihr, dass Ihr auf dem besten Wege seid, alle Säulen der Schöpfung an Euch zu bringen, aber Eure Arbeit noch längst nicht getan ist.>\n\n<Euer Orden hat die Inseln weiter nach allem durchkämmt, das hilfreich sein könnte. Es wäre das Beste, wenn Ihr Euch dort noch einmal erkundigt, bevor Ihr wieder abreist.>", sourceObjective = "Wählt Euren nächsten Angriffspunkt auf den Verheerten Inseln auf der Schlachtkarte in Eurer Ordenshalle aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44549] = { id = 44549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister der Inseln", description = "<Von dem sorgfältig ausgearbeiteten Plan die Verheerten Inseln im Sturm zu erobern und die Säulen der Schöpfung zu sammeln, ist nur noch eine Region übrig.>\n\n<Der Sieg ist in greifbarer Nähe, aber es würde nicht schaden, die Geheiminformationen Eures Ordens noch einmal anzusehen.>", sourceObjective = "Überprüft Euren letzten verbleibenden Angriffspunkt auf den Verheerten Inseln auf der Schlachtkarte in Eurer Ordenshalle aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44550] = { id = 44550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf nach Acherus", description = "<Todesgebieter/Todesgebieterin>, Eure Anwesenheit wird in Acherus erbeten.\n\nDer Krieg gegen die Brennende Legion tobt und die Ritter der Schwarzen Klinge warten auf weitere Befehle.\n\nBitte kehrt sobald es Euch möglich ist, nach Acherus zurück. Siouxsie die Banshee erwartet Eure Rückkehr.", sourceObjective = "Sprecht mit Siouxsie der Banshee in Acherus, der Schwarzen Festung. Ihr könnt 'Schwarzes Tor' verwenden, um dorthin zurückzukehren.", completion = "Endlich seid Ihr eingetroffen, Todesgebieter. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44551] = { id = 44551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 1" }
quests[44552] = { id = 44552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 2" }
quests[44553] = { id = 44553, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Capturing the Gateway 3" }
quests[44554] = { id = 44554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mythic Keystone Weekly Tracking Quest" }
quests[44555] = { id = 44555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Entdeckung", description = "Champion! Bitte kommt unverzüglich zur Violetten Zitadelle.\n\nIch habe eine Entdeckung gemacht, die ich Euch und dem Rat der Sechs vorstellen möchte.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Dalaran.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44556] = { id = 44556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan", description = "Karazhan befindet sich jetzt in den Händen der Legion, {name}.\n\nDas ist meine Schuld. In meiner Hast, Alodis Buch über die Säulen der Schöpfung in die Hände zu bekommen, habe ich nur unzureichende Schutzmaßnahmen für den Turm getroffen. Die Legion hat nicht lange gebraucht, um eine Schwachstelle zu finden.\n\nSeit der Zeit, als Sargeras Medivh kontrollierte, kennt er den Turm genauso gut wie ich. Was immer der dunkle Titan vorhat... Wir müssen ihn um jeden Preis aufhalten.\n\nIhr müsst sofort dorthin reisen. Trefft mich vor den Toren Karazhans!", sourceObjective = "Trefft Euch mit Khadgar außerhalb von Karazhan.", completion = "Es wartet Arbeit auf uns!", sourceObjectiveStatus = "unverified-source-field" }
quests[44557] = { id = 44557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endliche Zahlen", description = "Nicht alle meine Schutzzauber scheinen zerstört worden zu sein. Die Legion ist nicht in der Lage, die Portale im oder in der Nähe des Turms zu öffnen... zumindest noch nicht.\n\nSie scheinen weitere Kämpfer durch die Katakomben unterhalb des Gebirgspasses der Totenwinde hereinzubringen. Wenn Ihr sie ausschalten könnt, haben wir vielleicht genug Zeit, um sie aus Karazhan zu vertreiben.", sourceObjective = "Schließt 4 Portale und tötet 20 Dämonen am Gebirgspass der Totenwinde.", completion = "Gut gemacht! Zumindest befinden sich nun die meisten Dämonen, um die wir uns kümmern müssen, im Innern des Turms.\n\nEs kann sich um höchstens ein- oder zweitausend von ihnen handeln, da bin ich sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[44558] = { id = 44558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südlich von Burg Schattenfang im Silberwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 12 Mitarbeiter der Chemiemanufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport südlich von Burg Schattenfang im Silberwald zu zerstören, und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44559] = { id = 44559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rezept umsetzen", description = "Das scheint ein Teil eines Rezepts für irgendeinen Trank der Chemiemanufaktur Krone zu sein. Die anderen Teile müssten sich auch in der Nähe befinden.", sourceObjective = "Sammelt die anderen Teile des Rezepts der Chemiemanufaktur Krone ein und kehrt dann zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Aha! Damit können wir mit der Herstellung eines Gegenmittels für diese furchtbare Mixtur beginnen. Danke, dass Ihr mir das gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44560] = { id = 44560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rezept umsetzen", description = "Das scheint ein Teil eines Rezepts für irgendeinen Trank der Chemiemanufaktur Krone zu sein. Die anderen Teile müssten sich auch in der Nähe befinden.", sourceObjective = "Sammelt die anderen Teile des Rezepts der Chemiemanufaktur Krone ein und kehrt dann zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Aha! Damit können wir mit der Herstellung eines Gegenmittels für diese furchtbare Mixtur beginnen. Danke, dass Ihr mir das gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44561] = { id = 44561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saat der Hoffnung", description = "Thalyssra hat eine weise Entscheidung getroffen, Euch auf die Suche nach dem Arcan'dor zu schicken. Aber sie unterschätzt seine Macht.\n\nSie wird es noch lernen – so wie viele andere.\n\nAber dazu braucht es Zeit. Und da der Hunger die Seelen der Nachtsüchtigen aufzuzehren droht, brauchen sie dringend Eure Hilfe, um zu überleben.", sourceObjective = "Erreicht einen wohlwollenden Ruf bei den Nachtsüchtigen.", progress = "Der Arcan'dor braucht Zeit.", completion = "Die Zeit der Veränderung wird die Wahrheit enthüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44562] = { id = 44562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräftig wachsen", sourceObjective = "Erreicht einen respektvollen Ruf bei den Nachtsüchtigen.", progress = "Spürt Ihr das? Veränderung liegt in der Luft.", completion = "Wir werden den Shal'dorei helfen, endlich Harmonie zu erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44563] = { id = 44563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung für die Gefallenen", description = "Die Zeit der Veränderung ist nahe, und die Nachtsüchtigen werden ihr Schicksal selbst in die Hand nehmen.\n\nIhr habt ihnen Hoffnung geschenkt und sie auf den Pfad der Erlösung geführt. Sie brauchen Euch nun mehr als je zuvor.\n\nSo geht es uns allen.", sourceObjective = "Erreicht einen ehrfürchtigen Ruf bei den Nachtsüchtigen.", progress = "Es liegt viel vor uns.", completion = "Endlich können meine so lange verirrten Brüder in diese Welt zurückkehren. Elfen sollten unter einem sternenhellen Firmament leben – nicht unter einer Illusion davon.\n\nIch danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44569] = { id = 44569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inquisitor Volitix" }
quests[44570] = { id = 44570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in den Spitzen von Arak.", completion = "Ehrt die Flamme der Spitzen von Arak.", sourceObjectiveStatus = "unverified-source-field" }
quests[44571] = { id = 44571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in Talador.", completion = "Ehrt die Flamme von Talador.", sourceObjectiveStatus = "unverified-source-field" }
quests[44572] = { id = 44572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, {name}?", sourceObjective = "Ehrt das Sonnenwendfreudenfeuer in Nagrand.", completion = "Ehrt die Flamme von Nagrand.", sourceObjectiveStatus = "unverified-source-field" }
