quests[44616] = { id = 44616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das geht nicht ohne Obliterum", description = "Loramus Thalipedes hat angeboten, unsere Waffen zu verstärken. Er sagt, das Geheimnis hätte er Razelikh entlockt. Der Dämon weiß angeblich, wie man mit einem Material namens Obliterum arbeitet.\n\nIch habe selbst schon einiges an Informationen aus den Dämonen herausgeholt. Eine der Seelen, die in meiner Sense gefangen sind, hat mir einen Namen zugeflüstert: Camille Kleister. Ich weiß leider nur, dass sie irgendwo in Dalaran ist. Den Rest müsst Ihr selber herausfinden.", sourceObjective = "Findet Camille Kleister auf dem Handelsmarkt der Magier in Dalaran.", completion = "Ihr gehört zu den Dämonenjägern?\n\n<Instinktiv weicht der Mensch einen Schritt zurück.>", sourceObjectiveStatus = "unverified-source-field" }
