quests[44636] = { id = 44636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufbauen einer Armee", description = "Wir müssen unser Augenmerk fest auf die Zukunft richten. Es wird die Zeit kommen, wenn wir eine ganze Armee benötigen.\n\nWir haben bewiesen, dass es auch für die Verdorrten noch Erlösung gibt. Sie können lernen und sich ändern.\n\nIch möchte, dass Ihr sie im Kampf ausbildet, {name}. Kommt mit mir. Wir können die Ruinen hier in der Nähe als Arena nutzen, um ihre Fähigkeiten zu perfektionieren.", sourceObjective = "Sprecht mit Thalyssra, wenn Ihr bereit seid, die Verdorrten auf ihrer ersten Mission für das Kampftraining anzuführen.", sourceObjectiveStatus = "unverified-source-field" }
