quests[44659] = { id = 44659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I Skipped The Intro Tracking Quest" }
quests[44663] = { id = 44663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In einem flüchtigen Augenblick", description = "<Das Wesen spricht mit der vertrauten Stimme von Erzmagier Khadgar.>\n\nAzeroth braucht Euch, {name}!\n\nDurch die Suche nach Antworten in Ulduar und Karazhan kennen wir jetzt den Schlüssel zum Sieg über die Legion: Es sind die fünf uralten Artefakte, die wir die Säulen der Schöpfung nennen.\n\nUm sie zu finden, muss Dalaran zu den Verheerten Inseln verlegt werden. Und da unsere Anführerin Jaina... abwesend ist, hat Kalecgos vom blauen Drachenschwarm den Kirin Tor seine Hilfe angeboten.\n\nDie Legion greift zur Stunde unsere Position am Gebirgspass der Totenwinde an. Wir müssen uns beeilen!", sourceObjective = "Werdet Zeuge, wie Dalaran zu den Verheerten Inseln teleportiert wird.", completion = "Ah, {name}, schön, Euch wieder auf den Beinen zu sehen! Die Mitglieder des Rats der Sechs erholen sich von den Strapazen.\n\nDie Intensität des Teleportationszaubers kann dem Geist stark zusetzen. Anscheinend habt Ihr kurz das Bewusstsein verloren, aber immerhin seid Ihr nicht in einer Wand aufgewacht!\n\nDalaran wurde über die Verheerten Inseln versetzt. Von hier aus werden wir die Suche nach den Säulen der Schöpfung leiten und die Legion endgültig aus Azeroth vertreiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[44667] = { id = 44667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Valarjar", description = "Während wir unseren Angriff auf die Legion in ihrer eigenen Welt vorbereiten, ist es wichtig, dass wir gleichzeitig den Druck auf unsere Feinde in dieser Welt aufrechterhalten.\n\nWährend also unsere Armeen versuchen, die Portale der Feinde zu sichern, solltet Ihr am besten zu den Verheerten Inseln zurückkehren und unsere Gegner dort bekämpfen.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Ihr habt Euch gut geschlagen. Unsere Feinde fürchten jetzt Euch und Eure Armeen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44669] = { id = 44669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vicious Whale Shark" }
quests[44670] = { id = 44670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Broodmother Lizax" }
quests[44671] = { id = 44671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Muscle" }
quests[44672] = { id = 44672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Mana", description = "Da wir keinen Zugriff mehr auf den Nachtbrunnen haben, müssen meine Kameraden und ich von dem leben, was das Land uns bietet.\n\nDas uralte Mana, das aus den unterirdischen Leylinien an die Oberfläche dringt, kann viele Formen annehmen, am häufigsten aber sind Kristalle oder Edelsteine.\n\n<Thalyssra nimmt einen kleinen Stein auf, flüstert Worte der Macht und zeichnet mit ihrer Fingerspitze eine Rune darauf.>\n\nDieser Stein wird aufleuchten, wenn sich uraltes Mana in der Nähe befindet. Bitte sammelt so viel davon ein wie möglich! Wir werden in den kommenden Wochen darauf angewiesen sein.", sourceObjective = "Sammelt uraltes Mana von 3 uralten Manavorkommen.", progress = "Wir werden alles uralte Mana brauchen, das wir finden können. Bitte sorgt dafür, dass Ihr in der Lage seid, welches zu finden!", completion = "Achtet auf diese Kristallformationen in ganz Suramar. Wir werden sie brauchen.", sourceObjectiveStatus = "unverified-source-field" }
