quests[44679] = { id = 44679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Mana Tutorial Chest C" }
quests[44680] = { id = 44680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit gutem Beispiel voran", description = "Wir dürfen nicht zulassen, dass unsere gegenwärtige Situation die eigentliche Mission des Unsichtbaren Pfads, nämlich den Schutz der Einwohner von Azeroth, in Vergessenheit geraten lässt.\n\nAuf dieser Welt gibt es viele, die unserer Hilfe bedürfen.\n\nAls <unser Anführer/unsere Anführerin> solltet Ihr mit gutem Beispiel vorangehen und den Bedürftigen helfen.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Ihr seid eine Inspiration für uns alle, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44682] = { id = 44682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvergleichliche Macht", description = "Wir sind von Macht umgeben, {name}. Wir müssen nur lernen, sie zu beherrschen.\n\nZieht hinaus in die Welt und bedient Euch dieser Macht im Namen des Rates!\n\nWenn <unser bester Kämpfer/unsere beste Kämpferin> über unvergleichliche Macht verfügt, haben unsere Feinde keine Chance.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Eure innere Macht nimmt immer mehr zu, {name}. Ihr werdet dem Rat vorzüglich dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44683] = { id = 44683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stellung halten", description = "Karazhan befindet sich oberhalb eines Knotenpunktes von Leylinien. Maßgeblich aus diesem Grund wurde der Ort für den Turm gewählt. Und diese Tatsache ist auch der Legion nicht entgangen.\n\nWenn die Dämonen diese Energielinien anzapfen, benötigen sie die Energie sicher für etwas besonders Bedrohliches. Wenn wir den Turm zurückerobern wollen, müsst Ihr dafür sorgen, dass sie keinen Zugriff mehr auf die Leylinien haben, {name}.", sourceObjective = "Sichert die östliche Leylinie und die westliche Leylinie unterhalb von Karazhan.", completion = "Die Legion gerät ins Wanken. Bald werden wir zuschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[44684] = { id = 44684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdringende Verderbnis", description = "Die Legion hinterlässt überall die Fingerabdrücke ihrer Verderbnis. Wenn ich diese Magiespuren untersuche, kann ich vielleicht ihre Pläne für Karazhan aufdecken.\n\nDiese Phiole ist so verstärkt, dass sie Teufelsmagie aufnehmen kann. Wenn Ihr mir die verderbten Essenzen des Bodens und des Wassers aus der Nähe ihrer Portale bringen könnt, sollten wir Rückschlüsse auf ihr Vorhaben ziehen können.", sourceObjective = "Holt eine verderbte Essenz des Bodens und eine verderbte Essenz des Wassers aus den Höhlen unterhalb des Gebirgspasses der Totenwinde.", progress = "Was haben wir denn hier?", completion = "In jedem Bisschen ist eine gewisse Essenz enthalten, die wir studieren können, um etwas über den Magiewirker zu erfahren und wie wir seine Magie für... andere Zwecke anpassen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[44685] = { id = 44685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung der Stellungen", description = "Nach den Leylinien müssen wir jetzt auch den Turm sichern.\n\nIm gesamten Turmgebiet gibt es immer noch Orte, wo die Verderbnis außer Kontrolle ist. Begebt Euch an diese Orte und sichert sie mit diesen Zauberschutzen.\n\nWenn wir weiterhin so effektiv vorgehen und unsere Stellungen verstärken, sollten wir die verbleibenden Truppen der Legion so lange aufhalten können, bis wir wissen, wer hinter diesen Angriffen steckt.", sourceObjective = "Platziert die Zauberschutze an Orten im Osten, Süden und Norden des Turms am Gebirgspass der Totenwinde.", completion = "Ihr habt uns wertvolle Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[44686] = { id = 44686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhörprobe", description = "Während ich diese Proben genauer untersuche, würde ich Euch bitten, eine unserer Patrouillen in dem Bauwerk im Norden aufzusuchen. Wie es scheint, haben sie einen der Dämonen geschnappt.\n\nGeht und verhört ihn. Bringt so viel wie möglich in Erfahrung. Und beeilt Euch! Leider ist die Zeit nicht mehr auf unserer Seite.", sourceObjective = "Verhört die gefangene Wyrmzunge im Bauwerk etwas nördlich des Turms im Gebirgspass der Totenwinde.", completion = "Das ist genau die Information, die wir gebraucht haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44689] = { id = 44689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Tirisgarde", description = "Die Tirisgarde hat aus dem gesamten Gebiet der Verheerten Inseln Hilfegesuche für den Kampf gegen die Brennende Legion erhalten. Wir werden natürlich Erzmagier Vargoth weiter verfolgen, aber wir dürfen nicht vergessen, dass es unsere erste Pflicht ist, die Dämonen zurückzuschlagen und Azeroth zu beschützen.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Gut gemacht. Unter der Führung von Helden wie Euch ist die Tirisgarde eine Macht, mit der nicht zu spaßen ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[44690] = { id = 44690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durst nach Blut", progress = "Blut ist die Grundlage des Lebens und der Treibstoff für meine Kreationen. Leider aber gehen meine Vorräte zur Neige, und obendrein ist die Qualität in letzter Zeit recht enttäuschend gewesen.\n\nWenn meine untoten Kinder ihr volles Potenzial abrufen sollen, brauche ich reines Blut von höchster Qualität. Bringt mit das Blut von Sargeras. Dann werde ich damit meine edelsten Kreationen verstärken!", completion = "Endlich habe ich genug Blut von Sargeras, um meine Kreationen zu verstärken! Schon bald werdet Ihr sehen, was ich wirklich zu erschaffen in der Lage bin...\n\nUnd jetzt muss ich Euch bitten, mich bei der Arbeit allein zu lassen... Es gibt so viel zu tun und nicht mehr allzu viel Zeit!" }
quests[44691] = { id = 44691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Arbeit", description = "Wir müssen dafür sorgen, dass Großtelemant Oculeth so schnell wie möglich wieder auf die Beine kommt.\n\nIhr müsst unbedingt uraltes Mana finden und ihn damit nähren.", sourceObjective = "Nährt Großtelemant Oculeth mit uraltem Mana.", completion = "Ah, ich fühle mich schon viel besser. Danke!\n\nUnd jetzt an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[44694] = { id = 44694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schlacht nach der anderen", description = "Bevor ich Dämonenjäger wurde, habe ich mich mit den arkanen Künsten beschäftigt. Ich verfüge immer noch über etwas Wissen darüber, aber aufgrund des teuflischen Einflusses kann ich es nicht mehr in der Praxis anwenden.\n\nWas ich allerdings noch beherrsche, sind gelegentliche Ausblicke an entfernte Orte. Ihr habt selbst gesehen, wie ich dazu den Nethertiegel verwendet habe. Ich befürchte, dass die Lage kritisch ist.\n\nDie Kräfte, die sich gegen uns aufgestellt haben, beschränken sich nicht nur auf die Brennende Legion. Ihr müsst schnell handeln, bevor die Verheerten Inseln überrannt werden.", sourceObjective = "Schließt 10 Weltquests ab.", completion = "Ihr scheint exzellente Arbeit geleistet und viele Bedrohungen auf den Verheerten Inseln ausgeschaltet zu haben.\n\nIhr versteht es immer wieder, mich zu beeindrucken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44696] = { id = 44696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Daily - Watcher Osu" }
quests[44697] = { id = 44697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Prestige UI - Artifact" }
quests[44698] = { id = 44698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Bit" }
quests[44700] = { id = 44700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheim", description = "Gut, dass wir Euch gefunden haben, {name}!\n\nHimmelsadmiralin Rogers wünscht, Euch in Dalaran zu treffen. Es schien wichtig. Sie erwartet Euch in der Violetten Zitadelle.\n\nBeeilt Euch!", sourceObjective = "Sprecht mit Himmelsadmiralin Rogers in der Violetten Zitadelle in Dalaran.", completion = "Es ist mir eine Ehre, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44701] = { id = 44701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheim", description = "Gut, dass wir Euch gefunden haben, {name}!\n\nNathanos Pestrufer, Champion der Bansheekönigin selbst, wünscht, Euch in Dalaran zu sprechen. Es klang dringend. Er wartet in der Violetten Zitadelle auf Euch.\n\nBeeilt Euch!", sourceObjective = "Sprecht mit Nathanos Pestrufer in der Violetten Zitadelle in Dalaran.", completion = "<Nathanos schaut Euch kurz an und hält dann inne, bevor er Eure Anwesenheit zur Kenntnis nimmt.>\n\nJa?", sourceObjectiveStatus = "unverified-source-field" }
quests[44702] = { id = 44702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
