quests[44708] = { id = 44708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual of Doom" }
quests[44719] = { id = 44719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bresche in das Sanktum", description = "Die Zeit ist gekommen. Valtrois ist bereit, den Schild zu zerstören, der die Bresche im Sanktum schützt. Ich teleportiere Euch zur Bresche, von dort müsst Ihr den Bereich sichern.\n\nNehmt diese Telemantiekugeln. Falls Ihr Unterstützung braucht, könnt Ihr damit Verdorrte beschwören.\n\nWir müssen zuschlagen, bevor der Feind neue Verteidigungsmaßnahmen einleiten kann. Lasst mich wissen, wenn Ihr bereit seid, und wir beginnen.", sourceObjective = "Sprecht mit Oculeth, um den Angriff zu starten.", progress = "Wir haben es geschafft! Trotz anfänglicher Fehlschläge sind wir in der Lage, die Bresche zu betreten und unsere Kameraden zu befreien.", completion = "Für Eure Gabe, jede Notlage zu überwinden, verdient Ihr wahrlich meine Anerkennung. Lasst Euch beim Sammeln Eurer Champions etwas Zeit, {name}, aber nicht ZU viel Zeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[44720] = { id = 44720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Handeln gezwungen", description = "<Während der Rabe Euch tief in die Augen blickt, ertönt eine vertraute Stimme in Eurem Geist.>\n\nChampion, ich benötige Eure Hilfe. Es ist jetzt offensichtlich, was Helya vorhat.\n\nBereitet Euch vor und kommt dann zu mir.", sourceObjective = "Findet Havi in Valdisdall.", completion = "Gut, dass Ihr da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[44721] = { id = 44721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helyas Eroberung", description = "Wenn Helya auf die Verheerten Inseln vorrückt, müssen wir darauf vorbereitet sein.\n\nBegebt Euch zum Wellenskornhafen und kundschaftet ihre Truppen aus. Dann werden wir sehen, ob Helya töricht genug ist, ihren Feldzug gegen mich zu starten.", sourceObjective = "Sucht im Wellenskornhafen nach Hinweisen auf Helyas Streitkräfte.", progress = "Was plant Helya?", completion = "Sie hat mich dazu gezwungen...", sourceObjectiveStatus = "unverified-source-field" }
quests[44722] = { id = 44722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desillusionierter Deserteur", description = "Die Stimmung in der Stadt hat sich nur wenig gebessert, aber heute gereicht uns dies vielleicht zum Vorteil.\n\nSilgryn möchte, dass Ihr ihn an der Terrasse aufsucht. Selbst Elisandes Streitkräfte scheinen vor ihrem Wahnsinn zu fliehen.\n\nEin Deserteur aus ihren Reihen will sich uns anschließen.\n\nHeißt diese Person willkommen, {name}. In diesen finsteren Zeiten brauchen wir alle Freunde, die wir bekommen können.", sourceObjective = "Trefft Silgryn an der Immermondterrasse.", completion = "Schön, dass Ihr es geschafft habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44723] = { id = 44723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meinesgleichen", description = "Seid gegrüßt, <Fremder/Fremde>.\n\nIch bin Victoire. Ich habe Elisande gedient, solange sie für Frieden in der Stadt gesorgt hat. Zum Wohle der Allgemeinheit habe ich an der Seite von Dämonen und schlimmeren Kreaturen gekämpft.\n\nAber nach dem Massaker am Mondsichelforum ist es klar, dass sie nicht mehr den Nachtgeborenen, sondern nur noch sich selbst dient.\n\nEs gibt noch mehr von uns, die dieser Ansicht sind. Sie brauchen einfach nur einen Beweis, dass es einen anderen Weg gibt.\n\nWir wissen von der Dämmerlilie. Versucht, sie jenen zu zeigen, die den Hafen der Astravar bewachen. Sie haben Elisandes schlimmste Grausamkeiten mit eigenen Augen gesehen.", sourceObjective = "Wendet das Zeichen der Dämmerlilie auf die Unterwerfer der Dämmerwache an, um 5 Deserteure zu identifizieren.", progress = "Habt Ihr noch andere wie mich finden können?", completion = "Hoffentlich werden noch mehr ihrem Beispiel folgen.\n\nDanke, dass Ihr ihnen einen anderen Weg gezeigt habt, den Nachtgeborenen zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44724] = { id = 44724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermisstenmeldung", description = "Unsere neue Freundin hat ein paar beunruhigende Neuigkeiten übermittelt.\n\nSie sagt, sie hätte gesehen, wie eine große Anzahl Bürger in Ketten aus der Zuflucht des Sternenrufers abgeführt wurde. Ihr Ziel scheint der Hafen der Astravar gewesen zu sein.\n\nVom Hafen ist aber noch niemand zurückgekehrt. Und noch schlimmer ist, dass das ganze Gebiet von Dämonen überrannt wurde.\n\nIch möchte, dass Ihr herausfindet, was mit diesen Leuten geschehen ist. Untersucht den Hafen auf jegliche Hinweise.\n\nBeginnt mit den Kreaturen der Legion. Ihre Leichen könnten uns vielleicht den Weg weisen.", sourceObjective = "Beschafft einen Legionskommunikator von den Dämonen im Hafen der Astravar.", progress = "Konntet Ihr in Erfahrung bringen, wohin sie die Gefangenen gebracht haben?", completion = "<Silgryn starrt finster auf den Kommunikator.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44725] = { id = 44725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geiselnahme", description = "Unsere eigenen Leute werden der Legion geopfert!\n\nWir müssen einen Transport abfangen, wenn wir diesen Machenschaften ein Ende setzen wollen. Und ich befürchte, das bedeutet, dass Ihr <den Gefangenen/die Gefangene> spielen müsst.\n\nBevor Ihr Einspruch erhebt, habt einfach etwas Vertrauen in uns.\n\nWir werden in einem von Delines Booten dichtauf folgen und Euch befreien, sobald wir wissen, wo sie hinwollen.\n\nSucht jetzt im Hafen nach einer Gruppe Gefangener und mischt Euch unter sie. Lasst Euch willentlich gefangen nehmen.\n\nWir sind immer in Eurer Nähe.", sourceObjective = "Begebt Euch zum Hafen der Astravar und schließt Euch einer Gruppe Gefangener an, die in die Teufelsseelenbastion verbracht werden sollen.", completion = "Danke, dass Ihr das Risiko eingegangen seid. Lasst uns dieser Sache jetzt ein Ende bereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[44726] = { id = 44726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Seelengeschäft", description = "Wir werden hier die Position halten, während Ihr den für dieses Lager verantwortlichen Dämon findet und ausschaltet.\n\nDer Tod von Aargoss wird dieses Schmuggelgeschäft nicht dauerhaft unterbinden, aber vielleicht können wir sie dadurch so lange aufhalten, bis wir eine andere Lösung für diese Leute gefunden haben.\n\nBeeilt Euch. Er ist irgendwo da oben auf der Klippe.", sourceObjective = "Tötet Aargoss im Teufelsseelenvorstoß.", completion = "Gut gemacht. Lasst uns jetzt gehen, bevor sie Verstärkung anfordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[44727] = { id = 44727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmuggelt!", description = "Bitte holt mich hier raus!\n\nDie Stäbe sind brüchig, aber ich bin so schwach...\n\nDie anderen! Es gibt so viele andere! Bitte helft uns!", sourceObjective = "Befreit Maribeth und 5 Gefangene im Teufelsseelenvorstoß.", completion = "Danke. Wir hatten keine Hoffnung mehr auf Rettung, bevor Ihr kamt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44728] = { id = 44728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN" }
quests[44729] = { id = 44729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Tapferkeit: Odyns Gunst", description = "Es wird Zeit, dass wir uns um diese verräterische Hexe kümmern. Ich vermute, dass sie durch Eure Hand fallen wird, aber ich muss mir sicher sein.\n\nKommt zu mir in die Hallen der Tapferkeit, um Euch einer Prüfung Eures Willens zu unterziehen.", sourceObjective = "Sichert Euch Odyns Gunst im Schlachtzug \"Die Prüfung der Tapferkeit\".", completion = "Jetzt wartet eine größere Aufgabe auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44730] = { id = 44730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheerte Träume" }
quests[44731] = { id = 44731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schatz der Weißwasserschnellen" }
quests[44732] = { id = 44732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgalash" }
quests[44733] = { id = 44733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Verderbnis", description = "Endlich ist die Zeit gekommen.\n\nIn den Tiefen der Katakomben Karazhans liegt eine lang vergessene Kammer. Den Informationen zufolge, die Ihr unserem dämonischen Freund entlockt habt, wird das der Ort sein, an dem seine Herrin sich versteckt.\n\nDie Herrin dieses Dämons muss aus den höchsten Rängen der Brennenden Legion kommen. Das verheißt nichts Gutes für Karazhan.\n\nWir müssen den Gebirgspass der Totenwinde sichern, {name}.\n\nIhr müsst diesen Dämon finden und vernichten.", sourceObjective = "Nutzt die Verkleidung, um in die Kammer unterhalb von Karazhan im Gebirgspass der Totenwinde zu gelangen und Thar'zul und Elux'ara Dunkelzorn zu vernichten.", completion = "Unsere ärgsten Befürchtungen sind wahr geworden, {name}. Die Präsenz der Legion ist tief im Turm verankert.\n\nDie Zeit ist gekommen. Wir müssen Karazhan zurückerobern!", sourceObjectiveStatus = "unverified-source-field" }
quests[44734] = { id = 44734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Vergangenheit", description = "Auch wenn es unsere primäre Aufgabe ist, den Turm aus den Krallen der Legion zu befreien, habe ich eine... zusätzliche Bitte.\n\nKarazhan ist ein Ort, an dem Magie und Geschichte ineinander verflochten sind. Vergangene Ereignisse haben dort schon physische Gestalt angenommen, und solche Gestalten können große Macht besitzen.\n\nSucht auf Eurer Reise durch Karazhan nach Orten, an denen Erinnerungen sich so verdichten. Diese Fragmente könnten wertvolle Hinweise darauf geben, was wirklich in diesem Turm vor sich geht.", sourceObjective = "Sammelt die Seelenfragmente aus den Gästezimmern, dem Bankettsaal, den Bedienstetenunterkünften, dem Opernsaal und der Menagerie in Karazhan.", completion = "Die Geheimnisse des Turms sind so lange verborgen geblieben... Ich glaube, ich kenne meinen ehemaligen Meister nun ein wenig besser.\n\nIch bin dankbar, dass wir diese Reise unternommen haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44735] = { id = 44735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Im Auge des Betrachters", description = "Die Absichten der Legion sind klar. Sie haben vor, die magische Energie des Turms zu nutzen, um mit anderen Legionswelten zu kommunizieren!\n\nIch befürchte, wir haben nicht viel Zeit, {name}. Ihr müsst den Turm hinaufsteigen und diese Monstrosität vernichten, bevor es zu spät ist!", sourceObjective = "Bezwingt Viz'aduum den Beobachter in Karazhan.", completion = "Ich werde Eure heutigen Taten nicht vergessen, {name}.\n\nObwohl das Karazhan, das wir einst kannten, durch die Anwesenheit der Legion gezeichnet wurde, bin ich sicher, dass uns das Schicksal des Turms nicht enttäuschen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[44736] = { id = 44736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tore der Nachtfestung", description = "Unsere vereinten Armeen stehen vor dem Palast in Reih und Glied! Ich kann kaum glauben, dass die Zeit gekommen ist.\n\nEure verbündeten Kommandanten warten bereits, und wir werden dazustoßen. Begebt Euch zum Hafen der Astravar und sprecht mit Khadgar. Er wird den Angriff koordinieren... davon gehe ich zumindest aus.\n\nWir treffen uns dort... und vielen Dank für alles.", sourceObjective = "Begebt Euch zum Hafen der Astravar und beginnt gemeinsam mit den Elfen die Belagerung der Nachtfestung.", completion = "Danke, dass Ihr mich gerettet habt. Offenbar haben wir Elisandes Macht unterschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44737] = { id = 44737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft der Helarjar: Die Grauen Untiefen" }
quests[44738] = { id = 44738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die volle Macht der Elfen", description = "Thalyssra hat es geschafft, dass alle drei sich einigen konnten? Ihr Verhandlungsgeschick ist beeindruckend.\n\nAlso gut, <Held/Heldin>, Liadrin marschiert bereits auf Suramar. Schließt Euch ihren Truppen an.\n\nTyrande wird die Flanke der Stadtverteidigung angreifen und tiefer im Getümmel zu Euch stoßen.\n\nDie Nachtgeborenen bilden die Nachhut und halten das Gebiet für uns.\n\nOculeth und ich werden die Streitkräfte der Kirin Tor zum Hafen der Astravar verlegen. Mit etwas Glück werden wir auf der anderen Seite auf Euch treffen.", sourceObjective = "Führt die Armee der Elfen zum Hafen der Astravar.", completion = "Dank der telemantischen Fallen, die Ihr vor der Schlacht platziert habt, erleiden wir viel weniger Verluste.", sourceObjectiveStatus = "unverified-source-field" }
quests[44739] = { id = 44739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit zur Schlacht", description = "Dank Eurer Anstrengungen und jener unserer neuen Armee sind die Nachtsüchtigen für die Schlacht bereit.\n\nAußerdem konnten wir fast alle Zivilisten auf dem Weg von hier bis zum Hafen der Astravar in Sicherheit bringen.\n\nMeine Pläne werden unsere gemeinsamen Streitkräfte durch die Stadt führen und sie den Hafen erobern lassen.\n\nWürdet Ihr die Pläne bitte Vereesa, Tyrande und Liadrin überbringen?", sourceObjective = "Bringt die Pläne zu Vereesa Windläufer, Lady Liadrin und Tyrande Wisperwind.", completion = "Nun gut, mit diesen Plänen und ein wenig Glück könnten wir es mit weitaus weniger Kollateralschaden schaffen, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[44740] = { id = 44740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sammelpunkt", description = "Ihr und Eure Gefährten habt einen formidablen Korridor durch die Stadt geschlagen. Er wird schwer zu halten sein, aber dennoch einen Keil in Elisandes Truppen schlagen.\n\nOculeth war damit beschäftigt, einen telemantischen Signalgeber an diesen Standort zu verlegen, wollte aber Euch die Ehre der Aktivierung überlassen.", sourceObjective = "Aktiviert den Signalgeber von Astravar.", completion = "Gut gemacht, Held. Von diesem Sammelpunkt aus können unsere Truppen direkt auf die Stadttore zielen.\n\nThalyssra hat ihren Rebellen aufgetragen, den Ort für uns zu halten und uns Rückendeckung zu geben.\n\nSobald unsere Belagerungsfahrzeuge vor Ort sind, sollten wir für den Angriff auf die Stadt bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[44741] = { id = 44741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Die Tieftaschentheorie", description = "{name}, ich bin mir sicher, dass Ihr schon gehört habt, dass nur die Größe eines Beutels zählt. Ich bin nicht dieser Meinung. Ich glaube vielmehr, dass die Qualität eines Beutels ausschlaggebend ist.\n\nSchaut Euch nur mal diese zerlumpten Dinge an Euch an. Darin wirkt Ihr... nun, so gewöhnlich.\n\nIch werde es Euch beweisen. In Karazhan gibt es angeblich einige Beutel, die fast unendlich viele Dinge aufnehmen können. Aber die Materialien, die für ihre Herstellung vonnöten sind, sind so... Nun, das werdet Ihr schon selbst sehen.", sourceObjective = "Beschafft eine Tasche der tausend Fächer und eine Teufelssehnentasche aus Karazhan.", progress = "Nach dieser Lektion werde ich Euch hoffentlich nichts mehr beweisen müssen.", completion = "Und jetzt schaut genau zu.\n\n<Tytallo ergeht sich in einer langen Ausführung über Fadenzahl, Webtechniken und andere Details, die für Schneider hoch faszinierend sind.>\n\nIhr wirkt immer noch verwirrt. Hier, nehmt dieses Muster und seht selbst. Vielleicht lernt Ihr dann das ein oder andere.", sourceObjectiveStatus = "unverified-source-field" }
quests[44742] = { id = 44742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal des Schankwirts", description = "Ich habe Ly'leths Nachricht jetzt enträtseln können.\n\nIch möchte, dass Ihr mit mir zu ihrem Anwesen kommt. Es ist schon längst Zeit, dass ich in die Stadt zurückkehre.", sourceObjective = "Folgt Thalyssra zum Anwesen der Lunastres, um etwas über Vanthirs Schicksal zu erfahren.", progress = "Finstere Neuigkeiten wie diese können nicht warten.", completion = "Wir müssen sofort etwas unternehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44743] = { id = 44743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrandes Befehl", description = "Shal'Aran ist zum Platzen voll mit Flüchtlingen und Rebellen. Im Prinzip haben wir jetzt eine Armee, doch weder Waffen noch Mana reichen aus, um alle zu wappnen und vor dem Verdorren zu bewahren.\n\nUnd nebenbei hat Tyrande einen Haufen Anforderungen, für die ich nun wirklich keine Zeit habe.\n\nKönntet Ihr zu ihr gehen? Ihre wachsende Armee in Meredil ist schwer zu übersehen.", sourceObjective = "Sprecht mit Tyrande Wisperwind in Meredil.", completion = "Die Nachtsüchtigen haben darauf bestanden, eine Rolle in diesem Krieg zu spielen. Es gibt mehr Arbeit zu erledigen, als wir Leute haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44744] = { id = 44744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenslinien" }
quests[44746] = { id = 44746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ankunft der Helarjar: Die Beinharte Küste" }
quests[44748] = { id = 44748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflügelte Schrecken" }
quests[44751] = { id = 44751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Soldat wird zurückgelassen" }
quests[44752] = { id = 44752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenztriangulation", description = "Vanthir dient als... ein Exempel! Das erklärt, warum Elisande ihn so lange gefangen hielt.\n\nWir müssen uns beeilen. Ich kann ihn aufspüren, aber dazu müssen wir die Orte finden, an denen seine arkane Essenz am stärksten ist.\n\nIn einer so alten Stadt wie dieser ist dies keine einfache Aufgabe, aber mit etwas Glück gibt es hier ein paar Orte, die ihm wichtig genug waren, um dort etwas von sich selbst zurückzulassen.\n\nWir sollten mit der Promenade beginnen. Er hat sich dort oft aus geschäftlichen Gründen aufgehalten.", sourceObjective = "Helft Thalyssra, 3 arkane Essenzen von Vanthir zu sammeln.", completion = "Jetzt müssen wir uns nur noch auf seine Essenz konzentrieren, um seinen Standort zu bestimmen. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[44753] = { id = 44753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In aller Öffentlichkeit", description = "Jetzt, da ich Vanthirs Essenz unter den vielen Einwohnern Suramars ausfindig gemacht habe, kann ich womöglich seinen genauen Standort bestimmen.\n\nIhr erinnert Euch sicherlich noch an ein ähnliches Ritual mit unserem Freund Theryn. Aber keine Sorge, dieses Mal wird es weniger Geschrei geben. Hoffentlich.\n\nKommt. Lasst uns jetzt den verschollenen Schankwirt finden.", sourceObjective = "Helft Thalyssra, das Seherritual durchzuführen.", completion = "Das war... schwierig. Aber ich bin froh, dass wir es geschafft haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44754] = { id = 44754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mondsichelaufstand", description = "Ich weiß, wer ihn gefangen hält. Er ist einer von Aluriels Leutnants und ein geübter Zauberfechter. Ihr werdet Silgryns Hilfe brauchen, um den Schlüssel zu Vanthirs Gefängnis zu erlangen.\n\nDas Leben unseres Freundes hängt an einem seidenen Faden. Selbst wenn wir ihn aus den Fängen des Henkers befreien können, könnte er immer noch verdorren.\n\nIhr müsst ihm eine Frucht des Arcan'dor bringen. Sie sind selten und wertvoll, aber seine einzige Überlebenschance.\n\nBeeilt Euch. Und viel Glück.", sourceObjective = "Rettet Vanthir und gebt ihm eine Frucht des Arcan'dor.", progress = "<Vanthir zittert heftig und starrt ausdruckslos vor sich hin. Er scheint Eure Gegenwart nicht zu bemerken.>", completion = "<Vanthirs Hände schnellen nach oben und schnappen sich die Frucht aus Eurer Hand.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44756] = { id = 44756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeichen der Dämmerlilie", description = "Einfach nur... beeindruckend.\n\nSo einen klaren Verstand hatte ich schon seit Ewigkeiten nicht mehr.\n\nIch bin noch immer schwach... Ich muss mich ausruhen. Doch zuerst...\n\n<Vanthir deutet mit zitternder Hand zur Oberseite seines Käfigs.>\n\nZeigt ihnen, dass am heutigen Tag die Dämmerlilie triumphiert.", sourceObjective = "Platziert ein Zeichen der Dämmerlilie über Vanthirs Käfig.", completion = "Ich werde mich bei nächster Gelegenheit darum kümmern, dass er es angenehm hat. Wir haben heute einen bedeutenden Fortschritt erzielt, {name}.\n\nElisande weiß nun, dass wir die Unseren nicht einfach zurücklassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44758] = { id = 44758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist da drin?", description = "Wir sind wegen eines bestimmten Vorrats an Schießpulver hier. Er scheint mit einer Art Teufelskraft versetzt worden zu sein und ist... extrem reaktionsfreudig. Zurzeit hat ihn eine hiesige Piratenanführerin in ihrem Besitz.\n\nIhr solltet Meisterschützin Prix am hinteren Ende der Bucht antreffen, nahe des Wassers. Nehmt ihr ab, was wir brauchen.", sourceObjective = "Tötet Meisterschützin Prix und nehmt den Behälter mit teufelsberührtem Schießpulver an Euch.", progress = "Habt Ihr das Schießpulver beschafft?", completion = "Dieses Schießpulver ist der Schlüssel zu meinem Plan. Gut, dass Ihr es beschaffen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[44759] = { id = 44759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Tal der Angst" }
quests[44760] = { id = 44760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut an Euren Händen", sourceObjective = "Im Bereich dieser Inseln versucht sogar das Blut unserer Feinde, alles zu verderben. Aber Ihr wisst ja sicherlich, dass man dieses Blut extrahieren kann.\n\nWir Dämonenjäger verwenden dieses Blut für unsere eigenen Rituale, um uns für den Kampf gegen die Dämoneninvasion zu stärken.\n\nBringt mir so viel Blut von Sargeras, wie Ihr finden könnt, und ich werde mit Euch teilen, was ich habe.", sourceObjectiveStatus = "unverified-source-field" }
